.modal-two {
	position: fixed;
	inset: 0;
	z-index: $layer-modals;
	display: flex;
	padding: 3.5em;
	overflow: hidden;
	flex-flow: column nowrap;
	align-items: center;
	justify-content: center;
	animation: 0.1s ease-out forwards;
	animation-name: anime-modal-two-in;

	@include respond-to($breakpoint-small) {
		padding: 2em;
	}

	@include respond-to($breakpoint-tiny) {
		padding: 1em;
	}

	&--out {
		animation-name: anime-modal-two-out;
	}

	&--out &-dialog {
		animation-name: anime-modal-two-dialog-out;
	}

	&--fullscreen-on-mobile {
		@include respond-to($breakpoint-tiny) {
			padding: 0;
			align-items: stretch;
			background: none;
		}
	}

	&--fullscreen-on-mobile &-dialog {
		@include respond-to($breakpoint-tiny) {
			flex: 1 0 100%;
			border-radius: 0;
		}
	}

	&--fullscreen {
		padding: 0;
		align-items: stretch;
		background: none;
	}

	&--fullscreen &-dialog {
		flex: 1 0 100%;
		border-radius: 0;
		max-width: unset;
	}

	&--is-behind-backdrop {
		z-index: $layer-modals - 1;
	}

	@keyframes anime-modal-two-in {
		from {
			opacity: 0;
		}

		to {
			opacity: 1;
		}
	}

	@keyframes anime-modal-two-out {
		from {
			opacity: 1;
		}

		to {
			opacity: 0;
		}
	}

